import type { TableName } from '../table-names.js';
import {
  renderColumnDdl,
  renderCreateTable,
  renderSchema,
  type SchemaDef,
  type SchemaFlavour,
} from '../schema-model.js';
import { SCHEMA_VERSIONS, schemaAtVersion } from '../schema-versions.js';

/**
 * Migration DDL is **generated by diffing** consecutive schema versions per flavour — never
 * hand-written. Version 1 renders the whole schema; version N (N>1) diffs N-1 → N:
 *
 * - a table only in the new version → `CREATE TABLE`
 * - a column only in the new version → `ALTER TABLE … ADD COLUMN`
 *
 * Column type/flag changes and drops aren't emitted yet — no shipped version needs them, and a
 * portable rewrite (per flavour) should be added deliberately when one does, rather than guessed.
 * When you add/change a schema version in `schema-versions.ts`, the migration for it is produced
 * here automatically; there is nothing to hand-edit.
 */

type PhysicalName = (t: TableName) => string;

/** The DDL statements that take `prev`'s shape to `next`'s, for one flavour. */
export function diffSchema(
  prev: SchemaDef,
  next: SchemaDef,
  flavour: SchemaFlavour,
  physicalName: PhysicalName,
): string[] {
  const out: string[] = [];
  const prevTables = new Map(prev.tables.map((t) => [t.name, t]));
  for (const table of next.tables) {
    const before = prevTables.get(table.name);
    if (!before) {
      out.push(renderCreateTable(flavour, table, physicalName));
      continue;
    }
    const beforeCols = new Set(before.columns.map((c) => c.name));
    for (const col of table.columns) {
      if (!beforeCols.has(col.name)) {
        out.push(`ALTER TABLE ${physicalName(table.name)} ADD COLUMN ${renderColumnDdl(flavour, col)}`);
      }
    }
  }
  return out;
}

/** The DDL statements to apply schema `version` on a fresh-or-prior DB, for one flavour. */
export function migrationStatementsFor(
  version: number,
  flavour: SchemaFlavour,
  physicalName: PhysicalName,
): string[] {
  const schema = schemaAtVersion(version);
  if (version === SCHEMA_VERSIONS[0]!.version) {
    return renderSchema(flavour, schema, physicalName);
  }
  return diffSchema(schemaAtVersion(version - 1), schema, flavour, physicalName);
}
